            Brand of functional accessories<br/>for an active lifestyle
          </p>

          {/* Mobile Only Shopping Button */}
          <div className="md:hidden mt-12 mb-8">
            <Link 
              href="/catalog"
              className="bg-obsidian text-alabaster px-10 py-4 rounded-full text-[11px] font-sans font-bold uppercase tracking-[0.2em] inline-block shadow-xl active:scale-95 transition-transform"
            >
              START SHOPPING
            </Link>
          </div>
        </div>

        {/* Right Side: Image and Button */}
        <div className="w-full md:w-1/2 relative h-[50vh] sm:h-[60vh] md:h-[90vh] flex items-center justify-center animate-fade-in delay-200">
          <div className="relative w-[90%] md:w-full h-full md:h-[110%] md:-mt-12 bg-sand/30 overflow-hidden transform md:rounded-none rounded-t-[100px] shadow-2xl md:shadow-none md:hidden">
            <Image
              src="/images/products/1000545242.jpg.jpeg"
              alt="Hero Editorial"
              fill
              className="object-cover object-top scale-105 hover:scale-100 transition-transform duration-[2s] ease-out"
              priority
              quality={90}
              sizes="(max-width: 768px) 100vw, 50vw"
            />
          </div>

          {/* Pill Button overlaying image slightly on desktop */}
          <div className="absolute bottom-12 right-6 md:right-12 md:top-1/2 md:-translate-y-12 z-30 hidden md:block">
            <button 
              onClick={() => scrollToCategory(categoriesList[0])}
              className="bg-obsidian text-alabaster px-8 py-4 rounded-full text-[11px] font-sans font-bold uppercase tracking-[0.1em] hover:bg-obsidian/90 transition-colors shadow-lg hover:shadow-xl hover:scale-105 transform duration-300 inline-block"
            >
              SHOPPING
            </button>
          </div>
        </div>
      </section>

      {/* Split Collection Section */}
      <section className="min-h-[80vh] flex flex-col md:flex-row bg-[#E0DADC]/30">

        {/* Left: Categories List */}
        <div className="w-full md:w-1/2 p-8 py-16 md:p-24 flex flex-col justify-center border-b md:border-b-0 md:border-r border-obsidian/5">
          <div className="flex flex-col space-y-4 md:space-y-6 z-10">
            {categoriesList.map((cat, index) => (
              <button
                key={cat}
                onClick={() => scrollToCategory(cat)}
                className="text-left text-sm md:text-md font-sans uppercase tracking-[0.1em] text-obsidian hover:text-dustyrose transition-colors duration-300 w-fit group"
              >
                {cat}
