              </button>
            ))}
          </div>
        </div>

        {/* Right: Large Atmospheric Image with Text */}
        <div className="w-full md:w-1/2 relative h-[60vh] md:h-auto overflow-hidden group flex items-center justify-center bg-obsidian">
          <Image
            src="/images/products/1000545109.jpg.jpeg"
            alt="Summer Collection"
            fill
            className="object-cover transition-transform duration-[5s] group-hover:scale-105 opacity-80"
            sizes="(max-width: 768px) 100vw, 50vw"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-obsidian/80 to-transparent transition-opacity duration-[3s] group-hover:opacity-70 pointer-events-none"></div>

          <div className="relative z-30 flex flex-col items-center justify-center text-alabaster pointer-events-none p-6 text-center w-full h-full">
            <h2 className="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-sans font-bold tracking-tighter mix-blend-overlay drop-shadow-2xl">
