          <div className="md:hidden absolute top-[8%] sm:top-[15%] right-[5%] sm:right-[10%] w-[30%] sm:w-[35%] aspect-[3/4] z-20" style={{ animation: 'float 6s ease-in-out infinite' }}>
            <div className="relative w-full h-full rounded-t-full rounded-b-xl overflow-hidden shadow-2xl border border-sand/20 transform rotate-[6deg] group-hover:scale-105 transition-transform duration-700">
               <Image src="/images/products/1000544923.jpg.jpeg" alt="Summer Float 1" fill className="object-cover" />
               <div className="absolute inset-0 bg-gradient-to-tr from-obsidian/40 to-transparent mix-blend-overlay"></div>
            </div>
          </div>

          <div className="md:hidden absolute bottom-[8%] sm:bottom-[15%] left-[5%] sm:left-[10%] w-[35%] sm:w-[40%] aspect-square z-20" style={{ animation: 'float-reverse 8s ease-in-out infinite', animationDelay: '1s' }}>
             <div className="relative w-full h-full rounded-full overflow-hidden shadow-2xl border border-sand/20 transform rotate-[-8deg] group-hover:scale-105 transition-transform duration-700">
               <Image src="/images/products/1000544821.jpg.jpeg" alt="Summer Float 2" fill className="object-cover" />
               <div className="absolute inset-0 bg-gradient-to-tr from-obsidian/40 to-transparent mix-blend-overlay"></div>
             </div>
          </div>
        </div>

      </section>

      {/* Bestsellers Section */}
      <section id="shop" className="py-16 md:py-24 px-6 md:px-12 bg-alabaster">
        <div className="container mx-auto">

          {/* Header */}
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 md:mb-16 gap-6 md:gap-8 border-b border-obsidian/10 pb-6 md:pb-8">
            <div>
              <h2 className="text-3xl md:text-5xl font-sans font-bold tracking-tighter text-obsidian uppercase">BESTSELLERS</h2>
              <p className="mt-2 md:mt-4 text-xs md:text-sm text-obsidian/60 font-sans tracking-widest uppercase">
                Most Loved Items
              </p>
            </div>
          </div>

          {/* Product Grid - Desktop Grid */}
          <div className="hidden md:grid md:grid-cols-4 gap-4 md:gap-x-6 md:gap-y-12 pb-8">
            {products.slice(0, 4).map((product, index) => (
              <div 
                key={product.id} 
                className="animate-reveal"
                style={{ animationDelay: `${index * 150}ms` }}
              >
                <ProductCard product={product} />
              </div>
            ))}
          </div>

          {/* Product Slider - Mobile 3D Animation */}
          <MobileProductSlider products={products.slice(0, 4)} />

        </div>
      </section>

      {/* Category Sections */}
      {categoriesList.map((category, index) => {
        const categoryProducts = products.filter(p => p.category === category);
        const isEven = index % 2 === 0;
        return (
          <section 
            key={category} 
            id={`category-${category}`} 
            className={`py-16 md:py-24 px-6 md:px-12 ${isEven ? 'bg-sand/30' : 'bg-alabaster'}`}
          >
            <div className="container mx-auto">
              {/* Header */}
              <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 md:mb-16 gap-6 md:gap-8 border-b border-obsidian/10 pb-6 md:pb-8">
                <div>
                  <h2 className="text-3xl md:text-5xl font-sans font-bold tracking-tighter text-obsidian uppercase">
                    {category}
                  </h2>
                  <p className="mt-2 md:mt-4 text-xs md:text-sm text-obsidian/60 font-sans tracking-widest uppercase">
                    Curated Collection
                  </p>
                </div>
                <button 
                  onClick={() => scrollToCategory(category)}
                  className="hidden md:flex border border-obsidian text-obsidian px-6 md:px-8 py-2 md:py-3 rounded-full text-[10px] md:text-[11px] font-sans font-bold uppercase tracking-[0.1em] hover:bg-obsidian hover:text-alabaster transition-all duration-300 w-fit items-center gap-2 group"
                >
                  View All <ArrowUpRight size={14} className="transform group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                </button>
                <Link 
                  href={`/catalog?category=${category}`}
                  className="md:hidden border border-obsidian text-obsidian px-6 md:px-8 py-2 md:py-3 rounded-full text-[10px] md:text-[11px] font-sans font-bold uppercase tracking-[0.1em] hover:bg-obsidian hover:text-alabaster transition-all duration-300 w-fit flex items-center gap-2 group"
                >
                  View All <ArrowUpRight size={14} className="transform group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                </Link>
              </div>

              {/* Product Grid - Desktop Grid */}
              <div className="hidden md:grid md:grid-cols-4 gap-4 md:gap-x-6 md:gap-y-12 pb-8">
                {categoryProducts.map((product, idx) => (
                  <div 
                    key={product.id} 
                    className="animate-reveal"
                    style={{ animationDelay: `${idx * 150}ms` }}
                  >
                    <ProductCard product={product} />
                  </div>
                ))}
              </div>

              {/* Product Slider - Mobile 3D Animation */}
              <MobileProductSlider products={categoryProducts} />
            </div>
          </section>
        );
      })}

    </div>
  );
}

