"use client";

import React, { useCallback, useEffect, useState } from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import Image from 'next/image';
import { Product } from '@/data/products';
import { motion } from 'framer-motion';

export default function MobileProductGallery({ product }: { product: Product }) {
  const [emblaRef, emblaApi] = useEmblaCarousel({ loop: true });
  const [selectedIndex, setSelectedIndex] = useState(0);

  // Use the single image as an array, or if you had multiple images in your data structure, use those
  const images = [product.image];

  const scrollPrev = useCallback(() => {
    if (emblaApi) emblaApi.scrollPrev();
  }, [emblaApi]);

  const scrollNext = useCallback(() => {
    if (emblaApi) emblaApi.scrollNext();
  }, [emblaApi]);

  const onSelect = useCallback(() => {
    if (!emblaApi) return;
    setSelectedIndex(emblaApi.selectedScrollSnap());
  }, [emblaApi, setSelectedIndex]);

  useEffect(() => {
    if (!emblaApi) return;
    onSelect();
    emblaApi.on('select', onSelect);
    emblaApi.on('reInit', onSelect);
  }, [emblaApi, onSelect]);

  return (
    <div className="relative w-full h-[60vh] md:h-[80vh] bg-sand overflow-hidden group">
      <div className="overflow-hidden w-full h-full" ref={emblaRef}>
        <div className="flex w-full h-full touch-pan-y">
          {images.map((src, index) => (
            <div 
              className="relative flex-[0_0_100%] min-w-0 h-full flex items-center justify-center perspective-[1000px]" 
              key={index}
            >
              <motion.div
                 initial={{ opacity: 0, rotateY: 15, scale: 0.95 }}
                 animate={{ 
                    opacity: selectedIndex === index ? 1 : 0.4, 
                    rotateY: selectedIndex === index ? 0 : (index > selectedIndex ? 15 : -15),
                    scale: selectedIndex === index ? 1 : 0.95
                 }}
                 transition={{ duration: 0.6, ease: [0.32, 0.72, 0, 1] }}
                 className="relative w-full h-full"
              >
                 <Image
                    src={src}
                    alt={`${product.name} - Image ${index + 1}`}
                    fill
                    priority={index === 0}
                    quality={90}
                    className="object-cover"
                    sizes="(max-width: 768px) 100vw, 50vw"
                 />
              </motion.div>
            </div>
          ))}
        </div>
      </div>

       {images.length > 1 && (
        <>
            {/* Navigation Arrows */}
            <button
            className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-alabaster/80 backdrop-blur-md flex items-center justify-center text-obsidian shadow-lg opacity-0 md:group-hover:opacity-100 transition-opacity z-10"
            onClick={scrollPrev}
            >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
            </button>
            <button
            className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-alabaster/80 backdrop-blur-md flex items-center justify-center text-obsidian shadow-lg opacity-0 md:group-hover:opacity-100 transition-opacity z-10"
            onClick={scrollNext}
            >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
            </button>

            {/* Pagination Dots */}
            <div className="absolute bottom-6 left-0 right-0 flex justify-center gap-2 z-10">
            {images.map((_, index) => (
                <button
                key={index}
                className={`w-2 h-2 rounded-full transition-all duration-300 ${
                    index === selectedIndex ? 'bg-obsidian w-6' : 'bg-obsidian/40'
                }`}
                onClick={() => emblaApi?.scrollTo(index)}
                />
            ))}
            </div>
        </>
      )}
    </div>
  );
}

